
const WORDS=[{"id": 0, "w": "场面", "p": "chǎngmiàn", "t": "名词", "m": "cảnh (trong trường hợp nhất định), cảnh tượng", "coll": "热闹的场面、感人的场面", "s": "看到眼前热闹的场面，他立刻拿起相机记录下大家的笑容。"}, {"id": 1, "w": "端", "p": "duān", "t": "动词", "m": "bưng, mang", "coll": "端茶、端上桌", "s": "服务员小心地端着热汤穿过人群走到靠窗的桌子旁。"}, {"id": 2, "w": "盛", "p": "chéng", "t": "动词", "m": "chứa, đựng", "coll": "盛饭、盛满水", "s": "她用碗盛了一些水放在院子里留给路过的小猫。"}, {"id": 3, "w": "东张西望", "p": "dōng zhāng xī wàng", "t": "成语", "m": "nhìn ngang nhìn dọc", "coll": "东张西望、好奇地东张西望", "s": "第一次来到这里他好奇地东张西望想把周围的景物都看清楚。"}, {"id": 4, "w": "企图", "p": "qǐtú", "t": "动词／名词", "m": "mưu tính, mưu toan, định", "coll": "企图逃跑、企图掩盖", "s": "他企图掩盖事实，结果，却让事情变得更加复杂。"}, {"id": 5, "w": "动手", "p": "dòng shǒu", "t": "动词", "m": "ra tay, bắt đầu làm, giơ tay đánh/đập", "coll": "动手制作、自己动手", "s": "与其一直等待别人帮助不如自己动手试一试。"}, {"id": 6, "w": "纳闷儿", "p": "nà mènr", "t": "动词", "m": "cảm thấy bối rối, khó hiểu", "coll": "心里纳闷儿、感到纳闷儿", "s": "门明明没有锁里面却没有动静他心里不禁有些纳闷儿。"}, {"id": 7, "w": "跳跃", "p": "tiàoyuè", "t": "动词", "m": "nhảy", "coll": "跳跃运动、不断跳跃", "s": "小动物在树枝间不断跳跃动作很快让人几乎看不清。"}, {"id": 8, "w": "瞄准", "p": "miáozhǔn", "t": "动词", "m": "nhắm đúng, nhắm trúng", "coll": "瞄准目标、瞄准方向", "s": "运动员瞄准目标调整呼吸然后稳稳地射出了一箭。"}, {"id": 9, "w": "鸽子", "p": "gēzi", "t": "名词", "m": "chim bồ câu", "coll": "一群鸽子、喂鸽子", "s": "清晨，一群鸽子落在广场上悠闲地寻找食物。"}, {"id": 10, "w": "视线", "p": "shìxiàn", "t": "名词", "m": "ánh mắt, tầm mắt, đường ngắm", "coll": "遮挡视线、移开视线", "s": "前面的树枝遮挡了视线摄影师只好重新选择位置。"}, {"id": 11, "w": "周边", "p": "zhōubiān", "t": "名词", "m": "xung quanh", "coll": "周边环境、周边地区", "s": "开展调查前，我们先了解了学校周边的环境。"}, {"id": 12, "w": "颤抖", "p": "chàndǒu", "t": "动词", "m": "run rẩy, run", "coll": "身体颤抖、声音颤抖", "s": "站在寒风里他冻得身体颤抖连话都说不清楚了。"}, {"id": 13, "w": "确切", "p": "quèqiè", "t": "形容词", "m": "chuẩn xác, chính xác", "coll": "确切消息、确切含义", "s": "在获得确切消息之前，大家决定先保持联系不要随意猜测。"}, {"id": 14, "w": "迟钝", "p": "chídùn", "t": "形容词", "m": "không nhạy bén, không lanh lợi", "coll": "反应迟钝、感觉迟钝", "s": "连续工作很久以后，他开始感到反应迟钝决定停下来休息。"}, {"id": 15, "w": "迟缓", "p": "chíhuǎn", "t": "形容词", "m": "chậm chạp, chẳng hạn như rùa, lờ đờ", "coll": "行动迟缓、发展迟缓", "s": "这只年老的猫行动迟缓走到窗边以后便安静地卧了下来。"}, {"id": 16, "w": "庞大", "p": "pángdà", "t": "形容词", "m": "khổng lồ, to lớn", "coll": "体积庞大、庞大的系统", "s": "这个系统结构庞大需要多人合作才能完成日常维护。"}, {"id": 17, "w": "笨拙", "p": "bènzhuō", "t": "形容词", "m": "vụng về, lóng ngóng", "coll": "动作笨拙、显得笨拙", "s": "刚开始练习时，他的动作有些笨拙经过训练才逐渐熟练起来。"}, {"id": 18, "w": "比方", "p": "bǐfang", "t": "动词", "m": "ví dụ như, chẳng hạn như", "coll": "打个比方、比方说", "s": "为了说明问题，老师打了个比方把抽象的概念变得具体起来。"}, {"id": 19, "w": "间隔", "p": "jiàngé", "t": "动词", "m": "gián đoạn, cách nhau", "coll": "间隔时间、间隔相同", "s": "这两次观察间隔一个星期研究者分别记录了动物的活动情况。"}, {"id": 20, "w": "闪烁", "p": "shǎnshuò", "t": "动词", "m": "lấp lánh, lập lòe, lung linh", "coll": "灯光闪烁、星光闪烁", "s": "夜幕下，远处的灯光不停闪烁倒映在平静的水面上。"}, {"id": 21, "w": "视力", "p": "shìlì", "t": "名词", "m": "thị lực", "coll": "保护视力、视力检查", "s": "学校定期安排视力检查并提醒学生养成良好的用眼习惯。"}, {"id": 22, "w": "姑且", "p": "gūqiě", "t": "副词", "m": "tạm thời", "coll": "姑且相信、姑且不论", "s": "这个结论是否成立姑且不论我们先看看它的依据是什么。"}, {"id": 23, "w": "文雅", "p": "wényǎ", "t": "形容词", "m": "nho nhã, lịch sự", "coll": "举止文雅、谈吐文雅", "s": "这位老人谈吐文雅即使意见不同也总能平静地表达。"}, {"id": 24, "w": "犬", "p": "quǎn", "t": "名词", "m": "chó/(khuyển)", "coll": "搜救犬、警犬", "s": "经过训练的搜救犬进入现场协助工作人员寻找被困人员。"}, {"id": 25, "w": "系列", "p": "xìliè", "t": "名词", "m": "loạt, dãy", "coll": "一系列问题、系列活动", "s": "学校举办了一系列活动鼓励学生走近自然并记录观察结果。"}, {"id": 26, "w": "推论", "p": "tuīlùn", "t": "动词", "m": "suy luận, suy ra", "coll": "作出推论、合理推论", "s": "要作出合理的推论我们必须先确认现有证据是否可靠。"}, {"id": 27, "w": "本身", "p": "běnshēn", "t": "名词", "m": "bản thân", "coll": "问题本身、事物本身", "s": "讨论时，大家应该关注问题本身避免对个人进行攻击。"}, {"id": 28, "w": "新陈代谢", "p": "xīnchén dàixiè", "t": "名词", "m": "sự trao đổi chất", "coll": "新陈代谢过程、新陈代谢速度", "s": "这段材料介绍了新陈代谢的概念帮助学生理解相关研究的背景。"}, {"id": 29, "w": "能量", "p": "néngliàng", "t": "名词", "m": "năng lượng", "coll": "消耗能量、补充能量", "s": "这种设备消耗的能量较少，因此适合在野外长期使用。"}, {"id": 30, "w": "论证", "p": "lùnzhèng", "t": "动词", "m": "trình bày và chứng minh", "coll": "充分论证、论证观点", "s": "提出观点以后，作者用具体材料对自己的判断进行了论证。"}, {"id": 31, "w": "筛选", "p": "shāixuǎn", "t": "动词", "m": "chọn lọc, sàng, lọc", "coll": "筛选资料、筛选样本", "s": "为了提高分析质量，研究者先按照统一标准筛选了原始资料。"}, {"id": 32, "w": "标记", "p": "biāojì", "t": "名词／动词", "m": "đánh dấu, dán nhãn", "coll": "作出标记、标记位置", "s": "他在地图上标记位置方便下一次沿着同样的路线返回。"}, {"id": 33, "w": "名次", "p": "míngcì", "t": "名词", "m": "thứ hạng, thứ bậc", "coll": "取得名次、比赛名次", "s": "这次比赛，他没有过分在意名次，而是认真总结了自己的不足。"}, {"id": 34, "w": "感慨", "p": "gǎnkǎi", "t": "动词", "m": "cảm khái, xúc động thở dài", "coll": "深有感慨、感慨万千", "s": "再次走进旧校园看到熟悉的树木她心中感慨万千。"}, {"id": 35, "w": "渺小", "p": "miǎoxiǎo", "t": "形容词", "m": "nhỏ bé", "coll": "显得渺小、渺小的个体", "s": "站在辽阔的天地之间，他感到自己十分渺小也更加敬畏自然。"}, {"id": 36, "w": "攻击", "p": "gōngjī", "t": "动词", "m": "tấn công, công kích", "coll": "遭到攻击、攻击目标", "s": "面对不同意见，应当讨论观点的依据而不是攻击提出观点的人。"}, {"id": 37, "w": "势必", "p": "shìbì", "t": "副词", "m": "tất phải, ắt phải", "coll": "势必影响、势必造成", "s": "如果长期忽视这些细节，势必影响数据的质量也会增加后续工作的难度。"}, {"id": 38, "w": "博大精深", "p": "bódà jīngshēn", "t": "成语", "m": "rộng lớn và sâu sắc, uyên bác", "coll": "博大精深、博大精深的文化", "s": "这次学习让学生进一步感受到中国传统文化的博大精深。"}, {"id": 39, "w": "深奥", "p": "shēn'ào", "t": "形容词", "m": "sâu sắc, sâu xa, huyền bí", "coll": "内容深奥、深奥的理论", "s": "这段文字虽然内容深奥，却可以借助具体事例逐步理解。"}, {"id": 40, "w": "无能为力", "p": "wúnéngwéilì", "t": "成语", "m": "bất lực, không có sức mạnh", "coll": "感到无能为力、对此无能为力", "s": "面对突如其来的变化，他一度感到无能为力后来才慢慢找到解决办法。"}, {"id": 41, "w": "实惠", "p": "shíhuì", "t": "形容词", "m": "thực dụng, có ích, thiết thực", "coll": "经济实惠、实惠的选择", "s": "这家餐厅价格合理分量也足是一种经济实惠的选择。"}, {"id": 42, "w": "个体", "p": "gètǐ", "t": "名词", "m": "cá thể", "coll": "不同个体、个体差异", "s": "研究动物的行为时，不能忽略不同个体之间可能存在的差异。"}, {"id": 43, "w": "焦急", "p": "jiāojí", "t": "形容词", "m": "nôn nóng, lo lắng, sốt ruột", "coll": "焦急地等待、心情焦急", "s": "迟迟没有收到回信她焦急地等待着不时看看手机上的消息。"}];
